<?php require base_path('views/admin/_nav.php'); ?>
<form class="filter-bar" method="get"><select class="form-select" name="type"><option value="">All types</option><?php foreach(['Article','Error','SOP','Request'] as $v): ?><option <?=($_GET['type']??'')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['Draft','Published','Under Review','Archived'] as $v): ?><option <?=($_GET['status']??'')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><select class="form-select" name="system_id"><option value="">All systems</option><?php foreach($systems as $item):?><option value="<?=$item['id']?>" <?=(string)($_GET['system_id']??'')===(string)$item['id']?'selected':''?>><?=e($item['name'])?></option><?php endforeach;?></select><select class="form-select" name="category_id"><option value="">All categories</option><?php foreach($categories as $item):?><option value="<?=$item['id']?>" <?=(string)($_GET['category_id']??'')===(string)$item['id']?'selected':''?>><?=e($item['name'])?></option><?php endforeach;?></select><button class="btn btn-primary"><i class="bi bi-funnel"></i> Apply</button><a class="btn btn-outline-secondary" href="/admin/articles" title="Clear filters"><i class="bi bi-x-lg"></i></a></form>
<div class="panel"><div class="table-responsive"><table class="table admin-table align-middle"><thead><tr><th>Article</th><th>System</th><th>Severity</th><th>Status</th><th>Updated</th><th><span class="visually-hidden">Actions</span></th></tr></thead><tbody><?php foreach($articles as $article):?><tr><td><a href="/articles/<?=$article['id']?>"><strong><?=e($article['title'])?></strong><small><?=e($article['type'])?><?=$article['error_code']?' · '.e($article['error_code']):''?></small></a></td><td><?=e($article['system_name']??'General')?></td><td><?=$article['severity']?'<span class="badge '.severity_class($article['severity']).'">'.e($article['severity']).'</span>':'—'?></td><td><span class="badge text-bg-light border"><?=e($article['status'])?></span></td><td><?=date('M j, Y',strtotime($article['updated_at']))?></td><td><div class="table-actions"><a class="btn btn-sm btn-outline-primary" href="/admin/articles/<?=$article['id']?>/edit" title="Edit"><i class="bi bi-pencil"></i></a><form method="post" action="/admin/articles/<?=$article['id']?>/archive"><?=csrf_field()?><button class="btn btn-sm btn-outline-danger" data-confirm="Archive this article? It will be hidden but retained." title="Archive"><i class="bi bi-archive"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$articles):?><tr><td colspan="6"><div class="empty-table">No articles match these filters.</div></td></tr><?php endif;?></tbody></table></div></div>
